//! The `gbk` half of Python's `decode_body` fallback chain, as a generated
//! table. Every valid two-byte pair (`0x81..=0xFE` lead, `0x40..=0x7E` or
//! `0x80..=0xFE` trail) with the code point `bytes([b1, b2]).decode('gbk')`
//! yields on the pinned CPython 3.12.5 build — 21,791 pairs compressed into
//! runs of consecutive trails mapping to consecutive code points. A single
//! byte >= 0x80 never decodes alone (the gbk codec is strictly double-byte
//! above ASCII), so a lead byte without a valid trail is an error, exactly
//! like Python's UnicodeDecodeError.
//!
//! Regenerate with the pinned interpreter if this ever needs refreshing:
//! iterate b1 in 0x81..=0xFE, b2 in 0x40..=0x7E then 0x80..=0xFE, keep the
//! pairs that decode, compress consecutive (trail, codepoint) runs.

/// One run: lead byte, first trail, last trail, code point of the first pair.
/// Trails and code points both advance by one per step inside a run.
struct GbkRun(u8, u8, u8, u32);

