/// Decode a full byte slice as gbk, matching Python's strict
/// `bytes.decode('gbk')`: any invalid lead, invalid trail, or truncated
/// pair is an error (the caller falls through to the next charset).
pub fn decode_gbk(raw: &[u8]) -> Result<String, ()> {
    let mut out = String::with_capacity(raw.len());
    let mut i = 0;
    while i < raw.len() {
        let b = raw[i];
        if b < 0x80 {
            out.push(b as char);
            i += 1;
            continue;
        }
        if !(0x81..=0xFE).contains(&b) || i + 1 >= raw.len() {
            return Err(());
        }
        let t = raw[i + 1];
        // RUNS is sorted by (lead, trail); the runs for one lead are contiguous.
        let mut decoded = None;
        for r in RUNS {
            if r.0 == b && t >= r.1 && t <= r.2 {
                decoded = Some(char::from_u32(r.3 + (t - r.1) as u32).ok_or(())?);
                break;
            }
            if r.0 > b {
                break;
            }
        }
        match decoded {
            Some(c) => out.push(c),
            None => return Err(()),
        }
        i += 2;
    }
    Ok(out)
}
